(315, 163, 1, 'IT-Bridge', 'it-bridge', 'about-me/it-bridge', '{\"085d665e-182b-41aa-88d8-6d0f9b722b4e\":true,\"bd1b5efa-ac2b-4c86-82d8-0e6b43f5b706\":[156],\"1752fa62-54ea-499e-bf2f-4bb9c5f4c100\":[22],\"316aecc8-cfc8-4db8-be28-82e8a6729272\":[],\"6264dc36-2cad-4684-bc63-7e6b24864d21\":\"<p><strong>The IT-Bridge</strong></p><p>The IT-Bridge was a small company started by a man named Micheal Jordan in collaboration with the college i was studying at.The place itself was tucked into the back corner of the college building, with the agreement between the college and Mister Jordan being that he was allowed to work in this space, provided he would take in interns and manage some small things around the building, such as the digital displays in the hallway.</p><p>My job mainly consisted of whatever Mister Jordan would ask of me, whether that would be working on small Wordpress websites he would make for friends of his, tools to use around the IT-Bridge itself, or working on a website he was supposedly making for his son (which to this day is not in use, but feel free to check for yourself at <a href=\\\"https://bobjordan.nl\\\">https://bobjordan.nl</a>).</p>\"}', 1, '2024-12-11 19:46:31', '2024-12-11 20:20:40', '254c0a56-6063-4b52-b393-93205f9c5148'),
(316, 163, 2, 'IT-Bridge', 'it-bridge', 'about-me/it-bridge', '{\"085d665e-182b-41aa-88d8-6d0f9b722b4e\":true,\"bd1b5efa-ac2b-4c86-82d8-0e6b43f5b706\":[156],\"1752fa62-54ea-499e-bf2f-4bb9c5f4c100\":[22],\"316aecc8-cfc8-4db8-be28-82e8a6729272\":[],\"6264dc36-2cad-4684-bc63-7e6b24864d21\":\"<p><strong>The IT-Bridge</strong></p><p>The IT-Bridge was a small company started by a man named Micheal Jordan in collaboration with the college i was studying at.The place itself was tucked into the back corner of the college building, with the agreement between the college and Mister Jordan being that he was allowed to work in this space, provided he would take in interns and manage some small things around the building, such as the digital displays in the hallway.</p><p>My job mainly consisted of whatever Mister Jordan would ask of me, whether that would be working on small Wordpress websites he would make for friends of his, tools to use around the IT-Bridge itself, or working on a website he was supposedly making for his son (which to this day is not in use, but feel free to check for yourself at <a href=\\\"https://bobjordan.nl\\\">https://bobjordan.nl</a>).</p>\"}', 1, '2024-12-11 19:46:31', '2024-12-11 20:20:40', '5e377fa2-a652-4baf-8a26-e7bb5b91a875'),
