(705, 358, 1, 'Welkom', 'welcome', NULL, '{\"626f95f3-5540-4ee8-b558-882bab1436c9\":[{\"col1\":\"- Registreer nu\",\"col2\":\"register\"},{\"col1\":\"Maak connectie met mij\",\"col2\":\"connect\"},{\"col1\":\"Ontdek alles!\",\"col2\":\"everything\"},{\"col1\":\"- Onderhoud je computer\",\"col2\":\"maintain\"}],\"9a429db3-dedb-435d-8ee8-e7849ce0e654\":\"<p>Welkom in de opwindende nieuwe wereld van mijn portfolio, waar u mij ontmoet! </p><p>Leun achterover en ontspan terwijl u een korte rondleiding door de opties op dit scherm krijgt. </p><p>Als u een optie wilt verkennen, klikt u er gewoon op.</p>\"}', 1, '2024-12-15 15:46:47', '2024-12-15 15:46:47', '1f8230b3-ec38-4341-9bdd-5b2e1317a1ed'),
(706, 358, 2, 'Welcome', 'welcome', NULL, NULL, 1, '2024-12-15 15:46:47', '2024-12-15 15:46:47', 'bc9baf73-c7d6-4250-8060-959003ab76a7'),
(709, 360, 2, 'Welcome', 'welcome', NULL, '{\"626f95f3-5540-4ee8-b558-882bab1436c9\":[{\"col1\":\"- Register now\",\"col2\":\"register\"},{\"col1\":\"Connect to me\",\"col2\":\"connect\"},{\"col1\":\"Discover Everything!\",\"col2\":\"everything\"},{\"col1\":\"- Maintain your computer\",\"col2\":\"maintain\"}],\"9a429db3-dedb-435d-8ee8-e7849ce0e654\":\"<p>Welcome to the exciting new world of my portfolio, where you meet me!</p><p>Sit back and relax as you take a brief tour of the options available on this screen.</p><p>If you want to explore an option, just click it.</p>\"}', 1, '2024-12-15 15:50:54', '2024-12-15 15:50:54', '28596f0f-2a8d-47f5-8fde-4fc37ae3b983'),
(710, 360, 1, 'Welkom', 'welcome', NULL, '{\"626f95f3-5540-4ee8-b558-882bab1436c9\":[{\"col1\":\"- Registreer nu\",\"col2\":\"register\"},{\"col1\":\"Maak connectie met mij\",\"col2\":\"connect\"},{\"col1\":\"Ontdek alles!\",\"col2\":\"everything\"},{\"col1\":\"- Onderhoud je computer\",\"col2\":\"maintain\"}],\"9a429db3-dedb-435d-8ee8-e7849ce0e654\":\"<p>Welkom in de opwindende nieuwe wereld van mijn portfolio, waar u mij ontmoet! </p><p>Leun achterover en ontspan terwijl u een korte rondleiding door de opties op dit scherm krijgt. </p><p>Als u een optie wilt verkennen, klikt u er gewoon op.</p>\"}', 1, '2024-12-15 15:50:54', '2024-12-15 15:50:54', '5340c65e-711a-4d74-8109-09faffe06b3c'),
(711, 361, 1, 'Welkom', 'welcome', NULL, '{\"626f95f3-5540-4ee8-b558-882bab1436c9\":[{\"col1\":\"- Registreer nu\",\"col2\":\"register\"},{\"col1\":\"Maak connectie met mij\",\"col2\":\"connect\"},{\"col1\":\"Ontdek alles!\",\"col2\":\"everything\"},{\"col1\":\"- Onderhoud je computer\",\"col2\":\"maintain\"}],\"9a429db3-dedb-435d-8ee8-e7849ce0e654\":\"<p>Welkom in de opwindende nieuwe wereld van mijn portfolio, waar u mij ontmoet! </p><p>Leun achterover en ontspan terwijl u een korte rondleiding door de opties op dit scherm krijgt. </p><p>Als u een optie wilt verkennen, klikt u er gewoon op.</p>\"}', 1, '2024-12-15 15:51:28', '2024-12-15 15:51:28', '48d43d49-61a8-4982-bdf5-b7efaf6381bf'),
(712, 361, 2, 'Welcome', 'welcome', NULL, '{\"626f95f3-5540-4ee8-b558-882bab1436c9\":[{\"col1\":\"- Register now\",\"col2\":\"register\"},{\"col1\":\"Connect to me\",\"col2\":\"connect\"},{\"col1\":\"Discover Everything!\",\"col2\":\"everything\"},{\"col1\":\"- Maintain your computer\",\"col2\":\"maintain\"}],\"9a429db3-dedb-435d-8ee8-e7849ce0e654\":\"<p>Welcome to the exciting new world of my portfolio, where you meet me!</p><p>Sit back and relax as you take a brief tour of the options available on this screen.</p><p>If you want to explore an option, just click it.</p>\"}', 1, '2024-12-15 15:51:28', '2024-12-15 15:51:28', '2bdab162-702b-4775-90ba-7c8739d0bf58');

